import RNA,random,time
t='....((....((....((....((..((..((...))..))....))......)).......)).........)).............'
def dist(s): return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], t)
pi=[(4,74),(5,73),(10,63),(11,62),(16,54),(17,53),(22,46),(23,45),(26,40),(27,39),(30,36),(31,35)]
def mkseed():
    seq=['A']*len(t)
    for idx,(a,b) in enumerate(pi):
        k=random.choice(['GC','CG','AU','UA','GU','UG'])
        seq[a],seq[b]=k[0],k[1]
    seq[32]='G';seq[33]='A';seq[34]='A'  # GAAA tetraloop
    return ''.join(seq)
best=None;best_d=99
deadline=time.time()+120
seed=0
while time.time()<deadline:
    cur=mkseed(); cur_d=dist(cur)
    inner=time.time()+8
    while time.time()<inner and cur_d>0:
        c=list(cur)
        for _ in range(random.choice([1,1,2])):
            i=random.randrange(len(c)); c[i]=random.choice('ACGU')
        c=''.join(c); d=dist(c)
        if d<cur_d or (d==cur_d and random.random()<0.5):
            cur,cur_d=c,d
    if cur_d<best_d:
        best,best_d=cur,cur_d
        print(best_d,best,flush=True)
print('FINAL',best_d,best)
